public with sharing class ContactTriggerHandler {

    /**
     * Collects distinct non-null AccountIds referenced by the given contacts
     * and returns a map of AccountId -> Account with the fields needed by
     * this trigger (BillingCountry, AccountSource, Phone).
     * This issues exactly one SOQL query (or zero if there are no AccountIds).
     */
    private static Map<Id, Account> queryAccounts(List<Contact> contacts) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : contacts) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }

        Map<Id, Account> accountsById = new Map<Id, Account>();
        if (!accountIds.isEmpty()) {
            accountsById = new Map<Id, Account>(
                [SELECT Id, BillingCountry, AccountSource, Phone FROM Account WHERE Id IN :accountIds]
            );
        }
        return accountsById;
    }

    public static void beforeInsert(List<Contact> newContacts) {
        Map<Id, Account> accountsById = queryAccounts(newContacts);

        for (Contact c : newContacts) {
            if (c.AccountId != null) {
                Account a = accountsById.get(c.AccountId);
                if (a != null) {
                    if (String.isBlank(c.MailingCountry)) {
                        c.MailingCountry = a.BillingCountry;
                    }
                    if (String.isBlank(c.LeadSource)) {
                        c.LeadSource = a.AccountSource;
                    }
                }
            }
        }
    }

    public static void beforeUpdate(List<Contact> newContacts) {
        Map<Id, Account> accountsById = queryAccounts(newContacts);

        for (Contact c : newContacts) {
            if (c.AccountId != null) {
                Account a = accountsById.get(c.AccountId);
                if (a != null) {
                    if (String.isBlank(c.MailingCountry)) {
                        c.MailingCountry = a.BillingCountry;
                    }
                    // LeadSource is only defaulted on insert, matching original behaviour.
                }
            }
        }
    }

    public static void afterInsert(List<Contact> newContacts) {
        // Determine which accounts are referenced by contacts with a Phone value.
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : newContacts) {
            if (c.AccountId != null && String.isNotBlank(c.Phone)) {
                accountIds.add(c.AccountId);
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountsById = new Map<Id, Account>(
            [SELECT Id, Phone FROM Account WHERE Id IN :accountIds]
        );

        // Track which accounts currently have a blank phone (will be updated),
        // and ensure only the FIRST contact in trigger order sets it,
        // mirroring the original per-row early "first wins" behaviour.
        Set<Id> accountsAlreadyClaimed = new Set<Id>();
        List<Account> accountsToUpdate = new List<Account>();

        for (Contact c : newContacts) {
            if (c.AccountId == null || String.isBlank(c.Phone)) {
                continue;
            }

            Account a = accountsById.get(c.AccountId);
            if (a == null) {
                continue;
            }

            if (String.isBlank(a.Phone) && !accountsAlreadyClaimed.contains(a.Id)) {
                a.Phone = c.Phone;
                accountsAlreadyClaimed.add(a.Id);
                accountsToUpdate.add(a);
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
