public with sharing class ExchangeRateClient {

    public class ExchangeRateException extends Exception {}

    private static final Pattern CODE_PATTERN = Pattern.compile('^[A-Z]{3}$');

    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {
        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('Quote currency set must not be null or empty.');
        }

        String normalizedBase = normalizeCode(baseCurrency);
        if (!isValidCode(normalizedBase)) {
            throw new ExchangeRateException('Invalid base currency code: ' + baseCurrency);
        }

        Set<String> normalizedQuotes = new Set<String>();
        for (String quote : quoteCurrencies) {
            String normalizedQuote = normalizeCode(quote);
            if (!isValidCode(normalizedQuote)) {
                throw new ExchangeRateException('Invalid quote currency code: ' + quote);
            }
            normalizedQuotes.add(normalizedQuote);
        }

        List<String> sortedQuotes = new List<String>(normalizedQuotes);
        String symbolsParam = String.join(sortedQuotes, ',');

        String endpoint = 'callout:FB_Exchange_Rates/v1/latest?base='
            + EncodingUtil.urlEncode(normalizedBase, 'UTF-8')
            + '&symbols=' + EncodingUtil.urlEncode(symbolsParam, 'UTF-8');

        HttpRequest req = new HttpRequest();
        req.setEndpoint(endpoint);
        req.setMethod('GET');
        req.setHeader('Accept', 'application/json');

        Http http = new Http();
        HttpResponse res = http.send(req);

        if (res.getStatusCode() == 503) {
            res = http.send(req);
        }

        if (res.getStatusCode() != 200) {
            throw new ExchangeRateException(
                'Exchange rate request failed with status code: ' + res.getStatusCode()
            );
        }

        Map<String, Decimal> result = new Map<String, Decimal>();
        try {
            Map<String, Object> parsed = (Map<String, Object>) JSON.deserializeUntyped(res.getBody());
            Object ratesObj = parsed.get('rates');
            if (!(ratesObj instanceof Map<String, Object>)) {
                throw new ExchangeRateException('Response body missing rates object.');
            }
            Map<String, Object> rates = (Map<String, Object>) ratesObj;

            for (String code : normalizedQuotes) {
                if (!rates.containsKey(code) || rates.get(code) == null) {
                    throw new ExchangeRateException('No rate returned for requested currency: ' + code);
                }
                result.put(code, (Decimal) rates.get(code));
            }
        } catch (ExchangeRateException e) {
            throw e;
        } catch (Exception e) {
            throw new ExchangeRateException('Failed to parse exchange rate response: ' + e.getMessage());
        }

        return result;
    }

    private static String normalizeCode(String code) {
        if (code == null) {
            return null;
        }
        return code.trim().toUpperCase();
    }

    private static Boolean isValidCode(String code) {
        if (code == null) {
            return false;
        }
        return CODE_PATTERN.matcher(code).matches();
    }
}
