/**
 * RecordSearchService
 *
 * Generic, security-aware record search utility used by admin "record finder"
 * Lightning components. Performs equality-filter SOQL queries with full
 * respect for the running user's object/field level security and sharing.
 */
public with sharing class RecordSearchService {

    public class SearchException extends Exception {}

    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        // --- Basic input validation -----------------------------------------
        if (String.isBlank(objectApiName)) {
            throw new SearchException('An object API name must be provided.');
        }
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('At least one field must be requested.');
        }
        if (maxRows == null || maxRows < 1 || maxRows > 200) {
            throw new SearchException('maxRows must be between 1 and 200.');
        }

        // --- Resolve object describe ----------------------------------------
        Schema.DescribeSObjectResult objDescribe = resolveObjectDescribe(objectApiName);

        if (!objDescribe.isAccessible()) {
            throw new SearchException('You do not have access to object: ' + objectApiName);
        }

        Map<String, Schema.SObjectField> fieldMap = objDescribe.fields.getMap();

        // --- Resolve & validate requested fields -----------------------------
        // Use a map keyed by lower-case field name to the actual API name (as defined on the object)
        List<String> resolvedSelectFields = new List<String>();
        Set<String> seenSelectFields = new Set<String>(); // avoid duplicate Id / fields in SELECT

        // Always select Id first
        Schema.DescribeFieldResult idDescribe = getFieldDescribe(fieldMap, 'Id', objectApiName);
        checkFieldReadable(idDescribe, objectApiName);
        resolvedSelectFields.add(idDescribe.getName());
        seenSelectFields.add(idDescribe.getName().toLowerCase());

        for (String f : fields) {
            if (String.isBlank(f)) {
                throw new SearchException('Field names cannot be blank.');
            }
            Schema.DescribeFieldResult dfr = getFieldDescribe(fieldMap, f, objectApiName);
            checkFieldReadable(dfr, objectApiName);
            String apiName = dfr.getName();
            if (!seenSelectFields.contains(apiName.toLowerCase())) {
                resolvedSelectFields.add(apiName);
                seenSelectFields.add(apiName.toLowerCase());
            }
        }

        // --- Resolve & validate filters, building bind-safe WHERE clause ----
        List<String> whereClauses = new List<String>();
        Map<String, Object> bindMap = new Map<String, Object>();
        Integer bindIndex = 0;

        if (filters != null && !filters.isEmpty()) {
            for (String rawKey : filters.keySet()) {
                if (String.isBlank(rawKey)) {
                    throw new SearchException('Filter field names cannot be blank.');
                }
                Schema.DescribeFieldResult dfr = getFieldDescribe(fieldMap, rawKey, objectApiName);
                checkFieldReadable(dfr, objectApiName);
                if (!dfr.isFilterable()) {
                    throw new SearchException('Field cannot be filtered: ' + rawKey);
                }

                String apiName = dfr.getName();
                Object value = filters.get(rawKey);

                String bindVarName = 'bind' + bindIndex;
                bindIndex++;

                // Coerce / validate value type against field type where sensible,
                // and bind safely to avoid injection entirely.
                Object coercedValue = coerceValueForField(dfr, value, rawKey);

                bindMap.put(bindVarName, coercedValue);
                whereClauses.add(apiName + ' = :' + bindVarName);
            }
        }

        // --- Resolve & validate order-by field --------------------------------
        String orderByApiName = null;
        if (String.isNotBlank(orderByField)) {
            Schema.DescribeFieldResult dfr = getFieldDescribe(fieldMap, orderByField, objectApiName);
            checkFieldReadable(dfr, objectApiName);
            if (!dfr.isSortable()) {
                throw new SearchException('Field cannot be used to order results: ' + orderByField);
            }
            orderByApiName = dfr.getName();
        }

        // --- Build the final SOQL --------------------------------------------
        String query = 'SELECT ' + String.join(resolvedSelectFields, ', ') +
            ' FROM ' + objDescribe.getName();

        if (!whereClauses.isEmpty()) {
            query += ' WHERE ' + String.join(whereClauses, ' AND ');
        }

        if (orderByApiName != null) {
            query += ' ORDER BY ' + orderByApiName + ' ASC';
        }

        query += ' LIMIT :limitBindVar';
        bindMap.put('limitBindVar', maxRows);

        // --- Execute with WITH USER_MODE equivalent: with sharing + stripInaccessible,
        //     but field/object checks are already enforced above. We additionally use
        //     Database.queryWithBinds for safe bind variable support.
        List<SObject> results;
        try {
            results = Database.queryWithBinds(
                query,
                bindMap,
                AccessLevel.USER_MODE
            );
        } catch (Exception e) {
            throw new SearchException('Error executing search query: ' + e.getMessage());
        }

        return results;
    }

    // =========================================================================
    // Helper methods
    // =========================================================================

    private static Schema.DescribeSObjectResult resolveObjectDescribe(String objectApiName) {
        Map<String, Schema.SObjectType> gd = Schema.getGlobalDescribe();
        String lowerName = objectApiName.toLowerCase();

        Schema.SObjectType targetType = null;
        for (String key : gd.keySet()) {
            if (key.toLowerCase() == lowerName) {
                targetType = gd.get(key);
                break;
            }
        }

        if (targetType == null) {
            throw new SearchException('Unknown object: ' + objectApiName);
        }

        return targetType.getDescribe();
    }

    private static Schema.DescribeFieldResult getFieldDescribe(
        Map<String, Schema.SObjectField> fieldMap,
        String fieldName,
        String objectApiName
    ) {
        String lowerName = fieldName.toLowerCase();
        Schema.SObjectField sObjField = null;

        for (String key : fieldMap.keySet()) {
            if (key.toLowerCase() == lowerName) {
                sObjField = fieldMap.get(key);
                break;
            }
        }

        if (sObjField == null) {
            throw new SearchException(
                'Field "' + fieldName + '" does not exist on object "' + objectApiName + '".'
            );
        }

        return sObjField.getDescribe();
    }

    private static void checkFieldReadable(Schema.DescribeFieldResult dfr, String objectApiName) {
        if (!dfr.isAccessible()) {
            throw new SearchException(
                'You do not have access to field "' + dfr.getName() + '" on object "' + objectApiName + '".'
            );
        }
    }

    /**
     * Validates / coerces an incoming filter value against the target field's
     * declared SOQL/Apex type. Values are always passed through bind variables,
     * so there's no SOQL-injection concern here; the goal of this method is
     * only to catch obviously malformed input early and normalize common types
     * (e.g. Strings representing dates/numbers coming from a UI layer).
     */
    private static Object coerceValueForField(Schema.DescribeFieldResult dfr, Object value, String rawKey) {
        if (value == null) {
            return null;
        }

        Schema.DisplayType fieldType = dfr.getType();

        try {
            switch on fieldType {
                when BOOLEAN {
                    if (value instanceof Boolean) {
                        return value;
                    } else if (value instanceof String) {
                        return Boolean.valueOf((String) value);
                    }
                }
                when DATE {
                    if (value instanceof Date) {
                        return value;
                    } else if (value instanceof Datetime) {
                        return ((Datetime) value).date();
                    } else if (value instanceof String) {
                        return Date.valueOf((String) value);
                    }
                }
                when DATETIME {
                    if (value instanceof Datetime) {
                        return value;
                    } else if (value instanceof String) {
                        return Datetime.valueOf((String) value);
                    }
                }
                when INTEGER {
                    if (value instanceof Integer) {
                        return value;
                    } else if (value instanceof Decimal) {
                        return ((Decimal) value).intValue();
                    } else if (value instanceof String) {
                        return Integer.valueOf((String) value);
                    }
                }
                when DOUBLE, CURRENCY, PERCENT {
                    if (value instanceof Decimal) {
                        return value;
                    } else if (value instanceof Double) {
                        return value;
                    } else if (value instanceof Integer) {
                        return value;
                    } else if (value instanceof String) {
                        return Decimal.valueOf((String) value);
                    }
                }
                when ID, REFERENCE {
                    if (value instanceof Id) {
                        return value;
                    } else if (value instanceof String) {
                        return (Id) ((String) value);
                    }
                }
                when else {
                    // STRING, PICKLIST, TEXTAREA, EMAIL, PHONE, URL, etc.
                    if (value instanceof String) {
                        return value;
                    }
                    // Fall through to generic return below for other scalar types
                    return value;
                }
            }
        } catch (Exception e) {
            throw new SearchException(
                'Invalid filter value for field "' + rawKey + '": ' + e.getMessage()
            );
        }

        // If none of the above type-specific branches matched/returned, just
        // pass the value through as-is (bind variables remain injection-safe).
        return value;
    }
}
