public with sharing class OrderPayloadParser {

    public class PayloadException extends Exception {}

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public static Order parse(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('Body is null or blank.');
        }

        Object parsed;
        try {
            parsed = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new PayloadException('Invalid JSON: ' + e.getMessage());
        }

        if (!(parsed instanceof Map<String, Object>)) {
            throw new PayloadException('JSON body is not an object.');
        }

        Map<String, Object> root = (Map<String, Object>) parsed;

        Order order = new Order();

        Object numberObj = root.get('number');
        if (numberObj == null || !(numberObj instanceof String) || String.isBlank((String) numberObj)) {
            throw new PayloadException('Missing or blank order number.');
        }
        order.orderNumber = (String) numberObj;

        Object dateObj = root.get('date');
        if (dateObj != null) {
            if (!(dateObj instanceof String)) {
                throw new PayloadException('Invalid date format.');
            }
            order.orderDate = parseIsoDate((String) dateObj);
        }

        Object currencyObj = root.get('currency');
        if (currencyObj != null) {
            if (!(currencyObj instanceof String)) {
                throw new PayloadException('Invalid currency.');
            }
            order.currencyCode = (String) currencyObj;
        }

        Object customerObj = root.get('customer');
        if (customerObj != null) {
            if (!(customerObj instanceof Map<String, Object>)) {
                throw new PayloadException('Invalid customer object.');
            }
            Map<String, Object> customerMap = (Map<String, Object>) customerObj;
            Object emailObj = customerMap.get('email');
            if (emailObj != null) {
                if (!(emailObj instanceof String)) {
                    throw new PayloadException('Invalid customer email.');
                }
                order.customerEmail = (String) emailObj;
            }
        }

        List<Line> lineList = new List<Line>();
        Decimal total = 0;

        Object linesObj = root.get('lines');
        if (linesObj != null) {
            if (!(linesObj instanceof List<Object>)) {
                throw new PayloadException('Invalid lines array.');
            }
            List<Object> rawLines = (List<Object>) linesObj;
            for (Object rawLine : rawLines) {
                if (!(rawLine instanceof Map<String, Object>)) {
                    throw new PayloadException('Invalid line entry.');
                }
                Map<String, Object> lineMap = (Map<String, Object>) rawLine;
                Line line = parseLine(lineMap);
                lineList.add(line);
                total += line.lineTotal;
            }
        }

        order.lines = lineList;
        order.total = total.setScale(2, System.RoundingMode.HALF_UP);

        return order;
    }

    private static Line parseLine(Map<String, Object> lineMap) {
        Line line = new Line();

        Object skuObj = lineMap.get('sku');
        if (skuObj == null || !(skuObj instanceof String) || String.isBlank((String) skuObj)) {
            throw new PayloadException('Missing sku on line.');
        }
        line.sku = (String) skuObj;

        Object qtyObj = lineMap.get('quantity');
        if (qtyObj == null) {
            throw new PayloadException('Missing quantity on line.');
        }
        Decimal qtyDecimal;
        try {
            qtyDecimal = toDecimal(qtyObj);
        } catch (Exception e) {
            throw new PayloadException('Invalid quantity on line.');
        }
        if (qtyDecimal <= 0) {
            throw new PayloadException('Quantity must be positive.');
        }
        line.quantity = qtyDecimal.intValue();

        Object priceObj = lineMap.get('unitPrice');
        if (priceObj == null) {
            throw new PayloadException('Missing unitPrice on line.');
        }
        Decimal priceDecimal;
        try {
            priceDecimal = toDecimal(priceObj);
        } catch (Exception e) {
            throw new PayloadException('Invalid unitPrice on line.');
        }
        if (priceDecimal < 0) {
            throw new PayloadException('unitPrice must not be negative.');
        }
        line.unitPrice = priceDecimal;

        Object discountObj = lineMap.get('discount');
        Decimal discountDecimal = 0;
        if (discountObj != null) {
            try {
                discountDecimal = toDecimal(discountObj);
            } catch (Exception e) {
                throw new PayloadException('Invalid discount on line.');
            }
        }
        line.discount = discountDecimal;

        Decimal rawTotal = line.unitPrice * line.quantity * (1 - line.discount);
        line.lineTotal = rawTotal.setScale(2, System.RoundingMode.HALF_UP);

        return line;
    }

    private static Decimal toDecimal(Object val) {
        if (val instanceof Integer) {
            return Decimal.valueOf((Integer) val);
        } else if (val instanceof Long) {
            return Decimal.valueOf((Long) val);
        } else if (val instanceof Double) {
            return Decimal.valueOf((Double) val);
        } else if (val instanceof Decimal) {
            return (Decimal) val;
        } else if (val instanceof String) {
            return Decimal.valueOf((String) val);
        }
        throw new PayloadException('Value is not numeric.');
    }

    private static Date parseIsoDate(String dateStr) {
        try {
            List<String> parts = dateStr.split('-');
            if (parts.size() != 3) {
                throw new PayloadException('Invalid date format.');
            }
            Integer y = Integer.valueOf(parts[0]);
            Integer m = Integer.valueOf(parts[1]);
            Integer d = Integer.valueOf(parts[2]);
            return Date.newInstance(y, m, d);
        } catch (PayloadException pe) {
            throw pe;
        } catch (Exception e) {
            throw new PayloadException('Invalid date format: ' + dateStr);
        }
    }

    public static String toAcknowledgement(Order order) {
        Map<String, Object> ack = new Map<String, Object>();
        ack.put('number', order.orderNumber);
        ack.put('status', 'RECEIVED');
        ack.put('lineCount', order.lines != null ? order.lines.size() : 0);
        ack.put('total', order.total);
        return JSON.serialize(ack);
    }
}
