/**
 * Queueable job that re-rates up to 200 Accounts per execution based on AnnualRevenue,
 * chaining itself until all provided Account Ids have been processed.
 */
public class AccountScoringJob implements Queueable {

    private static final Integer BATCH_SIZE = 200;

    private List<Id> accountIds;

    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = accountIds;
    }

    public void execute(QueueableContext context) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        Integer processCount = Math.min(BATCH_SIZE, accountIds.size());
        List<Id> currentBatch = new List<Id>();
        for (Integer i = 0; i < processCount; i++) {
            currentBatch.add(accountIds[i]);
        }

        List<Id> remaining = new List<Id>();
        if (accountIds.size() > processCount) {
            for (Integer i = processCount; i < accountIds.size(); i++) {
                remaining.add(accountIds[i]);
            }
        }

        List<Account> accountsToUpdate = [
            SELECT Id, AnnualRevenue
            FROM Account
            WHERE Id IN :currentBatch
        ];

        for (Account acc : accountsToUpdate) {
            acc.Rating = rate(acc.AnnualRevenue);
        }

        update accountsToUpdate;

        if (!remaining.isEmpty()) {
            System.enqueueJob(new AccountScoringJob(remaining));
        }
    }

    private static String rate(Decimal annualRevenue) {
        if (annualRevenue != null && annualRevenue >= 1000000) {
            return 'Hot';
        } else if (annualRevenue != null && annualRevenue >= 100000) {
            return 'Warm';
        } else {
            return 'Cold';
        }
    }

    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }
        return System.enqueueJob(new AccountScoringJob(accountIds));
    }
}
