public with sharing class OpportunityPipelineHandler {

    /**
     * Entry point called from OpportunityTrigger for all relevant after-DML contexts
     * (insert, update, delete, undelete). Recomputes the open pipeline amount and
     * open opportunity count for every Account potentially affected by this DML,
     * based on a fresh aggregate query against the database. This makes the logic
     * correct and idempotent across multiple DML statements in the same transaction
     * (e.g. the AccountTrigger re-updating open Opportunities, or Flow + Apex running
     * in sequence), and safe for bulk operations such as 200-record data loads.
     *
     * @param newList  Trigger.new (null/empty on delete)
     * @param oldList  Trigger.old (null/empty on insert)
     */
    public static void handle(List<Opportunity> newList, List<Opportunity> oldList) {
        Set<Id> accountIds = new Set<Id>();

        if (newList != null) {
            for (Opportunity o : newList) {
                if (o.AccountId != null) {
                    accountIds.add(o.AccountId);
                }
            }
        }

        if (oldList != null) {
            for (Opportunity o : oldList) {
                if (o.AccountId != null) {
                    accountIds.add(o.AccountId);
                }
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        recalculate(accountIds);
    }

    /**
     * Recomputes FB_Open_Pipeline__c and FB_Open_Opportunities__c for the given set
     * of Account Ids, based solely on the current state of Opportunity data in the
     * database. Accounts with no remaining open opportunities are explicitly set to
     * 0 / 0 rather than left blank.
     */
    private static void recalculate(Set<Id> accountIds) {
        // Default every affected account to zero; aggregate results will override
        // those that still have open opportunities.
        Map<Id, Decimal> pipelineByAccount = new Map<Id, Decimal>();
        Map<Id, Integer> countByAccount = new Map<Id, Integer>();

        for (Id accId : accountIds) {
            pipelineByAccount.put(accId, 0);
            countByAccount.put(accId, 0);
        }

        AggregateResult[] results = [
            SELECT AccountId acctId, SUM(Amount) totalAmount, COUNT(Id) totalCount
            FROM Opportunity
            WHERE AccountId IN :accountIds AND IsClosed = false
            GROUP BY AccountId
        ];

        for (AggregateResult ar : results) {
            Id accId = (Id) ar.get('acctId');
            Decimal sumAmount = (Decimal) ar.get('totalAmount');
            Integer cnt = (Integer) ar.get('totalCount');
            pipelineByAccount.put(accId, sumAmount == null ? 0 : sumAmount);
            countByAccount.put(accId, cnt == null ? 0 : cnt);
        }

        List<Account> accountsToUpdate = new List<Account>();

        // Query current values so we only update accounts whose rollups actually
        // changed, avoiding unnecessary DML/recursion of the AccountTrigger.
        Map<Id, Account> existingAccounts = new Map<Id, Account>([
            SELECT Id, FB_Open_Pipeline__c, FB_Open_Opportunities__c
            FROM Account
            WHERE Id IN :accountIds
        ]);

        for (Id accId : accountIds) {
            Account existing = existingAccounts.get(accId);
            if (existing == null) {
                continue;
            }

            Decimal newPipeline = pipelineByAccount.get(accId);
            Integer newCount = countByAccount.get(accId);

            Decimal currentPipeline = existing.FB_Open_Pipeline__c == null ? 0 : existing.FB_Open_Pipeline__c;
            Integer currentCount = existing.FB_Open_Opportunities__c == null ? 0 : existing.FB_Open_Opportunities__c.intValue();

            if (currentPipeline != newPipeline || currentCount != newCount) {
                accountsToUpdate.add(new Account(
                    Id = accId,
                    FB_Open_Pipeline__c = newPipeline,
                    FB_Open_Opportunities__c = newCount
                ));
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
