/**
 * Schedulable job that purges old FB_Integration_Log__c records.
 *
 * Deletion rules:
 *  - Records with Level__c != 'ERROR' (including blank) are deleted once
 *    they are more than 30 days old.
 *  - Records with Level__c = 'ERROR' are kept longer and are only deleted
 *    once they are more than 180 days old.
 */
public class LogPurgeJob implements Schedulable {

    private static final Integer STANDARD_RETENTION_DAYS = 30;
    private static final Integer ERROR_RETENTION_DAYS = 180;

    public LogPurgeJob() {
    }

    public void execute(SchedulableContext sc) {
        purgeLogs();
    }

    @TestVisible
    private void purgeLogs() {
        DateTime standardCutoff = DateTime.now().addDays(-STANDARD_RETENTION_DAYS);
        DateTime errorCutoff = DateTime.now().addDays(-ERROR_RETENTION_DAYS);

        List<FB_Integration_Log__c> toDelete = [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE (Level__c != 'ERROR' AND CreatedDate < :standardCutoff)
               OR (Level__c = 'ERROR' AND CreatedDate < :errorCutoff)
        ];

        if (!toDelete.isEmpty()) {
            delete toDelete;
        }
    }

    public static Id scheduleNightly() {
        String cronExpression = '0 0 2 * * ?';
        return System.schedule('Log purge (nightly)', cronExpression, new LogPurgeJob());
    }
}
