```apex
/**
 * Pushes newly created Accounts to the ERP system, one HTTP callout per Account,
 * so the ERP team can trace every account individually.
 *
 * Callouts are not allowed synchronously from a trigger (DML + callout in the
 * same transaction throws a CalloutException), and firing many synchronous
 * callouts in one trigger invocation would also exceed governor limits when
 * accounts are inserted in batches of up to 200 (max 100 callouts per
 * transaction, 10s each).
 *
 * To satisfy "one request per account" in a bulk-safe way, each account's
 * callout is performed by its own Queueable job. Jobs are chained: each job
 * makes exactly one callout for its account, then enqueues the next job for
 * the remaining accounts. This respects the 50-queued-jobs-per-transaction
 * limit (we only ever have one job enqueued at a time from this chain) and
 * the per-transaction callout limit.
 */
public with sharing class ErpCustomerSync {

    private static final String ENDPOINT = 'callout:ERP/api/customers';

    /**
     * Entry point called from the trigger. Captures the minimal data needed
     * (Id, Name, BillingCountry) for each new account and starts the chain.
     */
    public static void enqueueSync(List<Account> newAccounts) {
        if (newAccounts == null || newAccounts.isEmpty()) {
            return;
        }

        List<CustomerPayload> payloads = new List<CustomerPayload>();
        for (Account acc : newAccounts) {
            payloads.add(new CustomerPayload(acc.Id, acc.Name, acc.BillingCountry));
        }

        System.enqueueJob(new SyncJob(payloads, 0));
    }

    /**
     * Queueable that sends exactly one customer per callout, then chains to
     * the next index until all accounts in the original batch are processed.
     */
    public class SyncJob implements Queueable, Database.AllowsCallouts {

        private final List<CustomerPayload> payloads;
        private final Integer index;

        public SyncJob(List<CustomerPayload> payloads, Integer index) {
            this.payloads = payloads;
            this.index = index;
        }

        public void execute(QueueableContext context) {
            if (index >= payloads.size()) {
                return;
            }

            sendOne(payloads[index]);

            Integer nextIndex = index + 1;
            if (nextIndex < payloads.size()) {
                System.enqueueJob(new SyncJob(payloads, nextIndex));
            }
        }

        private void sendOne(CustomerPayload payload) {
            List<CustomerPayload> single = new List<CustomerPayload>{ payload };
            String body = JSON.serialize(single);

            HttpRequest req = new HttpRequest();
            req.setEndpoint(ENDPOINT);
            req.setMethod('POST');
            req.setHeader('Content-Type', 'application/json');
            req.setBody(body);

            Http http = new Http();
            HttpResponse res = http.send(req);

            // Error handling and retries are explicitly out of scope for this ticket.
            // We only guard against an unexpected status to aid debugging.
            if (res.getStatusCode() != 202) {
                System.debug(
                    LoggingLevel.WARN,
                    'ERP sync for Account ' + payload.salesforceId +
                    ' returned unexpected status ' + res.getStatusCode() +
                    ': ' + res.getBody()
                );
            }
        }
    }

    /**
     * Wire format expected by the ERP API.
     */
    public class CustomerPayload {
        public String salesforceId;
        public String name;
        public String country;

        public CustomerPayload(Id accountId, String accountName, String billingCountry) {
            this.salesforceId = accountId;
            this.name = accountName;
            this.country = billingCountry; // null when blank, as required
        }
    }
}
```

