public with sharing class FollowUpTaskService {

    /**
     * Creates a follow-up Task for each Opportunity passed in.
     * Uses a single bulk DML call (Database.insert with allOrNone = false)
     * so that one Task failing validation does not prevent the others
     * from being inserted, while still avoiding one DML statement per record.
     *
     * @param opportunityIds Opportunity Ids to create follow-up tasks for.
     * @return Set of Opportunity Ids whose Task could not be created.
     */
    public static Set<Id> createFollowUps(List<Id> opportunityIds) {
        Set<Id> failedOpportunityIds = new Set<Id>();

        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return failedOpportunityIds;
        }

