        Set<Id> uniqueOppIds = new Set<Id>(opportunityIds);

        Map<Id, Opportunity> oppsById = new Map<Id, Opportunity>(
            [
                SELECT Id, Name, OwnerId
                FROM Opportunity
                WHERE Id IN :uniqueOppIds
            ]
        );

        Date followUpDate = Date.today().addDays(7);

        List<Task> tasksToInsert = new List<Task>();
        List<Id> oppIdByTaskIndex = new List<Id>(); // parallel list mapping task index -> opportunity Id

        for (Id oppId : uniqueOppIds) {
            Opportunity opp = oppsById.get(oppId);

            // If the Opportunity doesn't exist (bad Id, no access, deleted, etc.)
            // we can't build a Task for it - treat as a failure.
            if (opp == null) {
                failedOpportunityIds.add(oppId);
                continue;
            }

            Task t = new Task();
            t.WhatId = opp.Id;
            t.OwnerId = opp.OwnerId;
            t.Subject = 'Follow up: ' + opp.Name;
            t.ActivityDate = followUpDate;
            t.Status = 'Not Started';
            t.Priority = 'Normal';

            tasksToInsert.add(t);
            oppIdByTaskIndex.add(opp.Id);
        }

        if (!tasksToInsert.isEmpty()) {
            List<Database.SaveResult> saveResults = Database.insert(tasksToInsert, false);

            for (Integer i = 0; i < saveResults.size(); i++) {
                if (!saveResults.get(i).isSuccess()) {
                    failedOpportunityIds.add(oppIdByTaskIndex.get(i));
                }
            }
        }

        return failedOpportunityIds;
    }
