public with sharing class AccountRatingService {

    private static final String RATING_HOT = 'Hot';
    private static final String RATING_WARM = 'Warm';
    private static final String RATING_COLD = 'Cold';

    private static final Decimal HOT_THRESHOLD = 100000;

    /**
     * Recalculates the Rating field for all given Accounts based on their
     * currently open Opportunities. Accepts a set of Ids so a whole batch of
     * Opportunity DML (e.g. up to 200 records from CPQ) can be processed in a
     * single future call, staying under the 50-future-calls-per-transaction
     * limit and avoiding duplicate work for accounts shared by multiple
     * opportunities in the same batch.
     */
    @future
    public static void recalculate(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // Track the highest amount among open opportunities, per account.
        // An account with no entry here has no open opportunities (Cold).
        Map<Id, Decimal> maxOpenAmountByAccount = new Map<Id, Decimal>();

        for (Opportunity opp : [
            SELECT AccountId, Amount, IsClosed
            FROM Opportunity
            WHERE AccountId IN :accountIds
            AND IsClosed = false
        ]) {
            Decimal amount = opp.Amount == null ? 0 : opp.Amount;
            Decimal currentMax = maxOpenAmountByAccount.get(opp.AccountId);

            if (currentMax == null || amount > currentMax) {
                maxOpenAmountByAccount.put(opp.AccountId, amount);
            }
        }

        List<Account> accountsToUpdate = new List<Account>();

        for (Id accountId : accountIds) {
            Decimal maxOpenAmount = maxOpenAmountByAccount.get(accountId);
            String newRating;

            if (maxOpenAmount == null) {
                newRating = RATING_COLD;
            } else if (maxOpenAmount >= HOT_THRESHOLD) {
                newRating = RATING_HOT;
            } else {
                newRating = RATING_WARM;
            }

            accountsToUpdate.add(new Account(
                Id = accountId,
                Rating = newRating
            ));
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
