public with sharing class LineItemDiscountHandler {

    /**
     * For every line in the batch whose Discount is null, set it to the
     * standard discount for its product. Lines that already have a
     * Discount value (including 0) are left untouched.
     *
     * To stay bulk-safe with up to 200 lines per opportunity (as sent by
     * our CPQ tool), we only call PricingRules.standardDiscountFor once
     * per distinct Product2Id, instead of once per line. The result is
     * cached in a map and reused for every line that references the same
     * product. This avoids exceeding the SOQL query governor limit, since
     * PricingRules.standardDiscountFor issues a query internally.
     */
    public static void applyStandardDiscounts(List<OpportunityLineItem> lines) {
        // Collect distinct product Ids for lines that need a discount.
        Set<Id> productIdsNeedingDiscount = new Set<Id>();
        for (OpportunityLineItem line : lines) {
            if (line.Discount == null && line.Product2Id != null) {
                productIdsNeedingDiscount.add(line.Product2Id);
            }
        }

        // Resolve the standard discount once per distinct product.
        Map<Id, Decimal> standardDiscountByProductId = new Map<Id, Decimal>();
        for (Id productId : productIdsNeedingDiscount) {
            standardDiscountByProductId.put(productId, PricingRules.standardDiscountFor(productId));
        }

        // Apply the cached discount to each line that still needs one.
        for (OpportunityLineItem line : lines) {
            if (line.Discount == null && line.Product2Id != null) {
                line.Discount = standardDiscountByProductId.get(line.Product2Id);
            }
        }
    }
}
