/**
 * Queueable job that creates a CSAT survey Task for each Case that was
 * closed in the triggering transaction and has a Contact (ContactId).
 *
 * Design notes:
 * - Accepts a list of Case Ids (not a single Id) so that bulk closes
 *   (list view mass actions, nightly API cleanup of up to 200 cases) only
 *   enqueue ONE Queueable job per transaction, staying well within the
 *   governor limit of 50 queued jobs per Apex transaction.
 * - Each Case's Task creation is independent: Database.insert is called
 *   with allOrNone = false so that a failure on one record (e.g. a
 *   validation rule on Task) does not prevent Tasks being created for the
 *   other cases in the same job.
 * - Querying Cases fresh inside the job (rather than trusting trigger data)
 *   ensures we have the latest ContactId/CaseNumber/IsClosed values, since
 *   the job may run some time after the triggering transaction committed,
 *   and protects against stale data if the Case changed again before the
 *   job executed.
 * - The vendor survey integration mentioned can be added as an additional
 *   step inside execute() (or chained via System.enqueueJob from here)
 *   without touching the trigger.
 */
public with sharing class CaseSurveyJob implements Queueable {

    private final List<Id> caseIds;

    public CaseSurveyJob(Id caseId) {
        this.caseIds = new List<Id>{ caseId };
    }

    public CaseSurveyJob(List<Id> caseIds) {
        this.caseIds = caseIds;
    }

    public void execute(QueueableContext context) {
        if (caseIds == null || caseIds.isEmpty()) {
            return;
        }

        List<Case> cases = [
            SELECT Id, CaseNumber, ContactId, IsClosed
            FROM Case
            WHERE Id IN :caseIds
            AND IsClosed = true
            AND ContactId != null
        ];

        if (cases.isEmpty()) {
            return;
        }

        Date dueDate = Date.today().addDays(2);
        List<Task> tasksToInsert = new List<Task>();

        for (Case c : cases) {
            tasksToInsert.add(new Task(
                WhatId = c.Id,
                WhoId = c.ContactId,
                Subject = 'CSAT survey: ' + c.CaseNumber,
                ActivityDate = dueDate,
                Status = 'Not Started'
            ));
        }

        // Partial success: one Task failing to insert (e.g. due to a
        // validation rule) does not prevent the others from being created.
        List<Database.SaveResult> results = Database.insert(tasksToInsert, false);

        for (Integer i = 0; i < results.size(); i++) {
            Database.SaveResult result = results[i];
            if (!result.isSuccess()) {
                for (Database.Error err : result.getErrors()) {
                    System.debug(LoggingLevel.ERROR,
                        'CaseSurveyJob: failed to create survey Task for Case ' +
                        cases[i].CaseNumber + ' (' + cases[i].Id + '): ' +
                        err.getStatusCode() + ' - ' + err.getMessage());
                }
            }
        }
    }
}
