/**
 * Handler for AccountTrigger.
 *
 * Business rule: when an Account's BillingCountry changes, propagate the new
 * BillingCountry to that Account's Contacts' MailingCountry, but only for
 * Contacts whose MailingCountry is currently blank OR equal to the Account's
 * *previous* BillingCountry (i.e. contacts who were "following" the HQ country).
 * Contacts with a different MailingCountry (working abroad) are left untouched,
 * as are Contacts of Accounts whose BillingCountry did not change.
 *
 * Bulk-safety notes:
 * - No queries or DML inside loops.
 * - The Contact query is scoped to only the Accounts that changed BillingCountry
 *   in this trigger invocation (at most 200 Accounts per the stated MDM batch size,
 *   and in general bounded by Trigger.new size), and is further filtered by the
 *   MailingCountry condition in SOQL itself, so we never pull more rows into heap
 *   than we might actually update. Querying the entire 2.3M-row Contact table on
 *   every Account update would blow heap and row limits and does not scale with
 *   the org's data volume - only the trigger's working set should drive query size.
 * - A single aggregated SOQL query covers all changed Accounts in the batch,
 *   avoiding a query-per-Account pattern.
 * - Database.update(..., false) is used so one bad row doesn't abort the whole
 *   batch of updates for unrelated contacts.
 */
public with sharing class AccountCountrySync {

    public static void syncContactMailingCountry(List<Account> newAccounts, Map<Id, Account> oldAccountMap) {
        // 1. Identify Accounts whose BillingCountry actually changed, and remember
        //    the old BillingCountry for each (needed for the "equal to previous" check).
        Map<Id, String> oldBillingCountryByAccountId = new Map<Id, String>();
        Map<Id, String> newBillingCountryByAccountId = new Map<Id, String>();

        for (Account acc : newAccounts) {
            Account oldAcc = oldAccountMap.get(acc.Id);
            if (oldAcc == null) {
                continue;
            }
            if (acc.BillingCountry != oldAcc.BillingCountry) {
                oldBillingCountryByAccountId.put(acc.Id, oldAcc.BillingCountry);
                newBillingCountryByAccountId.put(acc.Id, acc.BillingCountry);
            }
        }

        if (oldBillingCountryByAccountId.isEmpty()) {
            return; // nothing changed BillingCountry in this batch
        }

        Set<Id> changedAccountIds = oldBillingCountryByAccountId.keySet();

        // 2. Query only the Contacts that could possibly need an update: those
        //    belonging to a changed Account, with a blank MailingCountry OR a
        //    MailingCountry matching that Account's *previous* value. We can't
        //    bind a per-row "previous country" value into a single WHERE clause
        //    efficiently, so we pull blank-OR-nonblank candidates per account
        //    scope and finish the "equal to previous" filtering in Apex. To keep
        //    this a single query, we broaden the WHERE to AccountId IN (...)
        //    and MailingCountry = null OR MailingCountry != null (i.e. all
        //    contacts of changed accounts), then filter precisely in memory.
        //    This is safe because the result set is bounded by the number of
        //    contacts on at most 200 accounts, not the whole org.
        List<Contact> candidateContacts = [
            SELECT Id, AccountId, MailingCountry
            FROM Contact
            WHERE AccountId IN :changedAccountIds
        ];

        List<Contact> contactsToUpdate = new List<Contact>();

        for (Contact con : candidateContacts) {
            String previousBillingCountry = oldBillingCountryByAccountId.get(con.AccountId);
            String newBillingCountry = newBillingCountryByAccountId.get(con.AccountId);

            Boolean mailingIsBlank = String.isBlank(con.MailingCountry);
            Boolean mailingMatchesPreviousBilling =
                !mailingIsBlank && con.MailingCountry == previousBillingCountry;

            if (mailingIsBlank || mailingMatchesPreviousBilling) {
                con.MailingCountry = newBillingCountry;
                contactsToUpdate.add(con);
            }
        }

        if (!contactsToUpdate.isEmpty()) {
            Database.update(contactsToUpdate, false);
        }
    }
}
