```javascript
import { LightningElement } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

const DEBOUNCE_DELAY = 300;
const MIN_SEARCH_LENGTH = 2;

export default class ContactSearch extends LightningElement {
    contacts = [];
    errorMessage;

    debounceTimeout;
    requestSequence = 0;
    isConnected = false;

    connectedCallback() {
        this.isConnected = true;
    }

    disconnectedCallback() {
        this.isConnected = false;
        if (this.debounceTimeout) {
            clearTimeout(this.debounceTimeout);
            this.debounceTimeout = null;
        }
    }

    get hasContacts() {
        return this.contacts && this.contacts.length > 0;
    }

    handleChange(event) {
        const rawValue = event.target.value;
        const trimmedValue = rawValue ? rawValue.trim() : '';

        // Cancel any pending debounce timer on every keystroke.
        if (this.debounceTimeout) {
            clearTimeout(this.debounceTimeout);
            this.debounceTimeout = null;
        }

        if (trimmedValue.length < MIN_SEARCH_LENGTH) {
            // Bump sequence so any in-flight response is ignored, then clear results.
            this.requestSequence++;
            this.contacts = [];
            this.errorMessage = undefined;
            return;
        }

        this.debounceTimeout = setTimeout(() => {
            this.debounceTimeout = null;
            this.executeSearch(trimmedValue);
        }, DEBOUNCE_DELAY);
    }

    executeSearch(searchTerm) {
        if (!this.isConnected) {
            return;
        }

        const currentSequence = ++this.requestSequence;

        searchContacts({ searchTerm })
            .then((results) => {
                if (!this.isConnected) {
                    return;
                }
                if (currentSequence !== this.requestSequence) {
                    // A newer request has since been issued; ignore this stale response.
                    return;
                }
                this.contacts = results;
                this.errorMessage = undefined;
            })
            .catch((error) => {
                if (!this.isConnected) {
                    return;
                }
                if (currentSequence !== this.requestSequence) {
                    return;
                }
                this.contacts = [];
                this.errorMessage =
                    (error && error.body && error.body.message) || 'Unknown error';
            });
    }
}
