import { LightningElement, api } from 'lwc';
import getOpenOpportunities from '@salesforce/apex/OpportunityController.getOpenOpportunities';

export default class OpenOpportunities extends LightningElement {
    @api recordId;

    isLoading = false;
    opportunities;
    hasError = false;
    errorMessage;

    connectedCallback() {
        this.loadOpportunities();
    }

    loadOpportunities() {
        this.isLoading = true;
        this.hasError = false;
        this.errorMessage = undefined;

        getOpenOpportunities({ accountId: this.recordId })
            .then((result) => {
                this.opportunities = result;
                this.hasError = false;
                this.errorMessage = undefined;
            })
            .catch((error) => {
                this.opportunities = undefined;
                this.hasError = true;
                this.errorMessage = this.extractErrorMessage(error);
            })
            .finally(() => {
                this.isLoading = false;
            });
    }

    extractErrorMessage(error) {
        if (error && error.body && error.body.message) {
            return error.body.message;
        }
        if (error && error.message) {
            return error.message;
        }
        return 'Unknown error';
    }

    handleRetry() {
        this.loadOpportunities();
    }

    get hasOpportunities() {
        return Array.isArray(this.opportunities) && this.opportunities.length > 0;
    }

    get isEmpty() {
        return Array.isArray(this.opportunities) && this.opportunities.length === 0;
    }
}
