import { LightningElement, api, track } from 'lwc';

const NAV_KEYS = ['ArrowDown', 'ArrowUp', 'Home', 'End'];
const SELECT_KEYS = ['Enter', ' '];

export default class StatusListbox extends LightningElement {
    @api label;

    @track _options = [];
    @track _value = '';
    @track activeValue = '';

    _rawOptions = [];

    @api
    get options() {
        return this._rawOptions;
    }
    set options(val) {
        this._rawOptions = val || [];
        this.syncActiveFromValue();
    }

    @api
    get value() {
        return this._value;
    }
    set value(val) {
        this._value = val;
        this.syncActiveFromValue();
    }

    syncActiveFromValue() {
        const opts = this._rawOptions || [];
        if (this._value && opts.some((o) => o.value === this._value)) {
            this.activeValue = this._value;
        } else if (opts.length > 0) {
            // If current activeValue is still valid among options, keep it only if it matches value logic
            const activeStillValid = opts.some((o) => o.value === this.activeValue);
            if (!this._value) {
                if (!activeStillValid) {
                    this.activeValue = opts[0].value;
                }
            } else {
                this.activeValue = opts[0].value;
            }
        } else {
            this.activeValue = '';
        }
    }

    get displayOptions() {
        const opts = this._rawOptions || [];
        return opts.map((opt) => {
            const isSelected = opt.value === this._value;
            const isActive = opt.value === this.activeValue;
            return {
                value: opt.value,
                label: opt.label,
                id: this.makeId(opt.value),
                ariaSelected: isSelected ? 'true' : 'false',
                isActive
            };
        });
    }

    makeId(value) {
        return `${this.listboxId}-option-${this.sanitize(value)}`;
    }

    sanitize(value) {
        return String(value).replace(/[^a-zA-Z0-9_-]/g, '_');
    }

    get listboxId() {
        return 'status-listbox';
    }

    get activeDescendantId() {
        if (!this.activeValue) {
            return undefined;
        }
        return this.makeId(this.activeValue);
    }

    getOptionsArray() {
        return this._rawOptions || [];
    }

    getActiveIndex() {
        const opts = this.getOptionsArray();
        return opts.findIndex((o) => o.value === this.activeValue);
    }

    moveActive(newIndex) {
        const opts = this.getOptionsArray();
        if (newIndex < 0 || newIndex >= opts.length) {
            return;
        }
        this.activeValue = opts[newIndex].value;
    }

    selectActive() {
        const opts = this.getOptionsArray();
        const active = opts.find((o) => o.value === this.activeValue);
        if (!active) {
            return;
        }
        if (active.value !== this._value) {
            this._value = active.value;
            this.dispatchEvent(
                new CustomEvent('change', {
                    detail: { value: active.value }
                })
            );
        }
    }

    handleKeyDown(event) {
        const key = event.key;
        const opts = this.getOptionsArray();
        if (opts.length === 0) {
            return;
        }

        if (NAV_KEYS.includes(key) || SELECT_KEYS.includes(key)) {
            event.preventDefault();
        } else {
            return;
        }

        const currentIndex = this.getActiveIndex();

        switch (key) {
            case 'ArrowDown':
                this.moveActive(currentIndex === -1 ? 0 : currentIndex + 1);
                break;
            case 'ArrowUp':
                this.moveActive(currentIndex === -1 ? 0 : currentIndex - 1);
                break;
            case 'Home':
                this.moveActive(0);
                break;
            case 'End':
                this.moveActive(opts.length - 1);
                break;
            case 'Enter':
            case ' ':
                this.selectActive();
                break;
            default:
                break;
        }
    }

    handleOptionClick(event) {
        const clickedValue = event.currentTarget.dataset.value;
        const opts = this.getOptionsArray();
        const option = opts.find((o) => String(o.value) === String(clickedValue));
        if (!option) {
            return;
        }
        this.activeValue = option.value;
        this.selectActive();
    }
}
