```apexclass
/**
 * Service for synchronizing a Contact's current employer (Organization Account)
 * using NPSP Affiliations. Relies on NPSP's AFFL_Affiliations_TDTM trigger handler
 * to automatically:
 *   - demote any previous primary Affiliation to Former / non-primary with an EndDate
 *   - update Contact.npsp__Primary_Affiliation__c to the new Organization
 * when a new Current + Primary Affiliation is inserted for a Contact.
 */
public with sharing class EmployerService {

    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        Set<Id> contactIds = employerByContactId.keySet();

        // SOQL #1: current primary affiliation per contact (to skip no-op cases)
        Map<Id, Id> currentPrimaryOrgByContactId = new Map<Id, Id>();
        for (Contact c : [
            SELECT Id, npsp__Primary_Affiliation__c
            FROM Contact
            WHERE Id IN :contactIds
        ]) {
            currentPrimaryOrgByContactId.put(c.Id, c.npsp__Primary_Affiliation__c);
        }

        // Determine which contacts actually need a new affiliation
        // (i.e. target org differs from the contact's current primary affiliation).
        Set<Id> contactsNeedingUpdate = new Set<Id>();
        for (Id contactId : contactIds) {
            Id targetOrgId = employerByContactId.get(contactId);
            if (targetOrgId == null) {
                continue;
            }
            Id existingPrimaryOrgId = currentPrimaryOrgByContactId.get(contactId);
            if (existingPrimaryOrgId != targetOrgId) {
                contactsNeedingUpdate.add(contactId);
            }
        }

        if (contactsNeedingUpdate.isEmpty()) {
            return;
        }

        // SOQL #2: check for an existing Affiliation record between each contact
        // and its *target* organization (regardless of status), so we don't create
        // an exact duplicate if one already exists (e.g. a Former record for the
        // same org that should simply be reinstated rather than duplicated).
        Set<Id> targetOrgIds = new Set<Id>();
        for (Id contactId : contactsNeedingUpdate) {
            targetOrgIds.add(employerByContactId.get(contactId));
        }

        Map<String, npe5__Affiliation__c> existingAfflByKey = new Map<String, npe5__Affiliation__c>();
        for (npe5__Affiliation__c affl : [
            SELECT Id, npe5__Contact__c, npe5__Organization__c, npe5__Status__c,
                   npe5__Primary__c, npe5__StartDate__c, npe5__EndDate__c
            FROM npe5__Affiliation__c
            WHERE npe5__Contact__c IN :contactsNeedingUpdate
              AND npe5__Organization__c IN :targetOrgIds
        ]) {
            String key = affl.npe5__Contact__c + ':' + affl.npe5__Organization__c;
            existingAfflByKey.put(key, affl);
        }

        List<npe5__Affiliation__c> toInsert = new List<npe5__Affiliation__c>();
        List<npe5__Affiliation__c> toUpdate = new List<npe5__Affiliation__c>();

        for (Id contactId : contactsNeedingUpdate) {
            Id targetOrgId = employerByContactId.get(contactId);
            String key = contactId + ':' + targetOrgId;
            npe5__Affiliation__c existing = existingAfflByKey.get(key);

            if (existing != null) {
                // Reinstate the existing affiliation record as the Current/Primary one.
                // NPSP's TDTM will still handle demoting whatever other affiliation
                // currently holds the Primary flag, and will update the Contact's
                // primary affiliation lookup.
                existing.npe5__Status__c = 'Current';
                existing.npe5__Primary__c = true;
                existing.npe5__EndDate__c = null;
                if (existing.npe5__StartDate__c == null) {
                    existing.npe5__StartDate__c = Date.today();
                }
                toUpdate.add(existing);
            } else {
                npe5__Affiliation__c newAffl = new npe5__Affiliation__c(
                    npe5__Contact__c = contactId,
                    npe5__Organization__c = targetOrgId,
                    npe5__Status__c = 'Current',
                    npe5__Primary__c = true,
                    npe5__StartDate__c = Date.today(),
                    npe5__Role__c = 'Employee'
                );
                toInsert.add(newAffl);
            }
        }

        // DML #1
        if (!toInsert.isEmpty()) {
            insert toInsert;
        }
        // DML #2
        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }
}
