/**
 * Service class for creating GAU Allocations by percentage split on an Opportunity.
 *
 * Allocations are stored with npsp__Percent__c set (not npsp__Amount__c), so that NPSP's
 * standard Allocation rollup/trigger logic recalculates npsp__Amount__c automatically whenever
 * the Opportunity Amount changes. This keeps the allocations correct over time without any
 * additional code.
 */
public class GauAllocationService {

    public class AllocationException extends Exception {}

    /**
     * Replaces all existing GAU Allocations on the given Opportunity with new percentage-based
     * allocations, one per entry in percentByGauId.
     *
     * @param opportunityId        Id of the Opportunity to allocate.
     * @param percentByGauId       Map of General Accounting Unit Id -> percent (e.g. 60 for 60%).
     * @return                     The newly inserted npsp__Allocation__c records.
     */
    public static List<npsp__Allocation__c> allocateByPercent(Id opportunityId, Map<Id, Decimal> percentByGauId) {
        validateInput(opportunityId, percentByGauId);

        Set<Id> gauIds = percentByGauId.keySet();

        validateGaus(gauIds);

        // Delete existing allocations for this Opportunity first (as part of the same
        // transaction - if anything below fails, this delete rolls back too).
        List<npsp__Allocation__c> existing = [
            SELECT Id
            FROM npsp__Allocation__c
            WHERE npsp__Opportunity__c = :opportunityId
        ];

        List<npsp__Allocation__c> newAllocations = new List<npsp__Allocation__c>();
        for (Id gauId : percentByGauId.keySet()) {
            npsp__Allocation__c alloc = new npsp__Allocation__c();
            alloc.npsp__Opportunity__c = opportunityId;
            alloc.npsp__General_Accounting_Unit__c = gauId;
            alloc.npsp__Percent__c = percentByGauId.get(gauId);
            newAllocations.add(alloc);
        }

        if (!existing.isEmpty()) {
            delete existing;
        }

        insert newAllocations;

        return newAllocations;
    }

    private static void validateInput(Id opportunityId, Map<Id, Decimal> percentByGauId) {
        if (opportunityId == null) {
            throw new AllocationException('Opportunity Id must be provided.');
        }

        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('percentByGauId must not be null or empty.');
        }

        Decimal total = 0;
        for (Id gauId : percentByGauId.keySet()) {
            if (gauId == null) {
                throw new AllocationException('GAU Id keys must not be null.');
            }

            Decimal pct = percentByGauId.get(gauId);
            if (pct == null || pct <= 0) {
                throw new AllocationException('Each percentage must be a non-null value greater than 0.');
            }

            total += pct;
        }

        if (total > 100) {
            throw new AllocationException('Percentages add up to more than 100%.');
        }
    }

    private static void validateGaus(Set<Id> gauIds) {
        Map<Id, npsp__General_Accounting_Unit__c> gauMap = new Map<Id, npsp__General_Accounting_Unit__c>(
            [
                SELECT Id, Name, npsp__Active__c
                FROM npsp__General_Accounting_Unit__c
                WHERE Id IN :gauIds
            ]
        );

        for (Id gauId : gauIds) {
            npsp__General_Accounting_Unit__c gau = gauMap.get(gauId);

            if (gau == null) {
                throw new AllocationException('General Accounting Unit not found: ' + gauId);
            }

            if (gau.npsp__Active__c != true) {
                throw new AllocationException('General Accounting Unit is inactive: ' + gau.Name);
            }
        }
    }
}
