/**
 * Service class used by the event check-in app to register an entire family
 * in one call, creating a single NPSP Household Account for all members.
 */
public with sharing class HouseholdService {

    /**
     * Inserts the given contacts so that they all belong to one new NPSP
     * Household Account. The first contact in the list becomes the
     * household's primary contact (npe01__One2OneContact__c).
     *
     * @param members list of new, un-inserted Contact records (no Id, no AccountId)
     * @return the Id of the newly created Household Account
     */
    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('members must not be null or empty');
        }

        // Defensive copy so we don't mutate the caller's list order/contents unexpectedly.
        Contact primary = members[0];

        // Make sure none of the incoming contacts already have an AccountId;
        // this service is meant for brand-new family registration.
        for (Contact c : members) {
            c.AccountId = null;
        }

        // Insert the primary contact first, with no AccountId set.
        // NPSP's standard Account/Household automation (Contacts_and_Orgs TDTM, etc.)
        // will detect the contact has no AccountId and automatically create a brand
        // new Household Account for them, using the correct Household Account
        // record type, NPSP naming, and greeting logic. We never touch record type
        // Ids or the Name field ourselves.
        insert primary;

        // Re-query to get the AccountId that NPSP's automation assigned.
        Contact insertedPrimary = [
            SELECT Id, AccountId
            FROM Contact
            WHERE Id = :primary.Id
        ];

        Id householdAccountId = insertedPrimary.AccountId;

        if (householdAccountId == null) {
            // Should not happen under normal NPSP configuration, but guard anyway.
            throw new HouseholdServiceException(
                'NPSP did not create a Household Account for the primary contact.'
            );
        }

        // Attach every remaining member to that same household account before
        // insert, so NPSP's automation does not spin up a separate household
        // for each of them.
        List<Contact> rest = new List<Contact>();
        for (Integer i = 1; i < members.size(); i++) {
            Contact c = members[i];
            c.AccountId = householdAccountId;
            rest.add(c);
        }

        if (!rest.isEmpty()) {
            insert rest;
        }

        // Explicitly set the household's primary contact to the first contact
        // in the list, regardless of what NPSP may have defaulted it to.
        Account household = new Account(
            Id = householdAccountId,
            npe01__One2OneContact__c = insertedPrimary.Id
        );
        update household;

        return householdAccountId;
    }

    public class HouseholdServiceException extends Exception {}
}
