public with sharing class FamilyService {

    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // Collect all contact Ids involved (both children and parents)
        Set<Id> allContactIds = new Set<Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            allContactIds.add(childId);
            Id parentId = parentIdByChildId.get(childId);
            if (parentId != null) {
                allContactIds.add(parentId);
            }
        }

        if (allContactIds.isEmpty()) {
            return;
        }

        // Single SOQL query: find any existing relationship records involving
        // any of our contacts, in either direction field.
        Set<String> existingPairKeys = new Set<String>();
        for (npe4__Relationship__c rel : [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE npe4__Contact__c IN :allContactIds
               OR npe4__RelatedContact__c IN :allContactIds
        ]) {
            existingPairKeys.add(makePairKey(rel.npe4__Contact__c, rel.npe4__RelatedContact__c));
        }

        List<npe4__Relationship__c> toInsert = new List<npe4__Relationship__c>();
        Set<String> processedPairs = new Set<String>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId == null || parentId == null) {
                continue;
            }

            String pairKey = makePairKey(childId, parentId);

            if (existingPairKeys.contains(pairKey)) {
                continue;
            }
            if (processedPairs.contains(pairKey)) {
                continue;
            }
            processedPairs.add(pairKey);

            // Create relationship from the child's perspective: child -> parent is "Parent"
            // NPSP's trigger will auto-create the reciprocal (parent -> child) record
            // based on the Relationship Lookup settings (Son/Daughter/Child).
            npe4__Relationship__c relationship = new npe4__Relationship__c(
                npe4__Contact__c = childId,
                npe4__RelatedContact__c = parentId,
                npe4__Type__c = 'Parent',
                npe4__Status__c = 'Current'
            );
            toInsert.add(relationship);
        }

        if (!toInsert.isEmpty()) {
            insert toInsert;
        }
    }

    private static String makePairKey(Id contactA, Id contactB) {
        String a = String.valueOf(contactA);
        String b = String.valueOf(contactB);
        return (a < b) ? (a + '_' + b) : (b + '_' + a);
    }
}
